// Filter: only process files with #task tag and status: pending
const payload = $input.first().json;

const commits = payload.commits || [];
const addedFiles = commits.flatMap(c => c.added || []);
const modifiedFiles = commits.flatMap(c => c.modified || []);
const allFiles = [...addedFiles, ...modifiedFiles];

// Only files in /TASKS/ folder
const taskFiles = allFiles.filter(f => f.startsWith('TASKS/') && f.endsWith('.md'));

if (taskFiles.length === 0) {
  return []; // Nothing to process — halt workflow
}

return taskFiles.map(filePath => ({
  json: {
    file_path: filePath,
    commit_hash: payload.after || 'unknown',
    repo: payload.repository?.full_name || 'unknown',
    pushed_at: new Date().toISOString()
  }
}));

// Validate and sanitize task note content before passing to agent
const item = $input.first().json;

const BLOCKED_PATTERNS = [
  /eval\s*\(/gi,
  /exec\s*\(/gi,
  /\.\.\//g,
  /<script/gi,
  /DROP\s+TABLE/gi,
  /DELETE\s+FROM/gi,
  /system\s*\(/gi
];

// Content comes from file read step — validate here
const content = item.file_content || '';

for (const pattern of BLOCKED_PATTERNS) {
  if (pattern.test(content)) {
    throw new Error(`GATE1_BLOCKED: Injection pattern detected in ${item.file_path}: ${pattern}`);
  }
}

return [{
  json: {
    ...item,
    sanitized: true,
    gate1_passed: true,
    gate1_timestamp: new Date().toISOString()
  }
}];

