// Gate 2: Validate agent output schema
import { z } from 'zod'; // Note: install via n8n npm packages

// Parse Claude response
const response = $input.first().json;
const rawContent = response.content?.[0]?.text || '';

let parsed;
try {
  // Strip any accidental markdown fences
  const cleaned = rawContent.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error(`GATE2_INVALID_JSON: Agent returned non-JSON: ${rawContent.substring(0, 200)}`);
}

// Schema validation
const validComplexity = ['low', 'medium', 'high'];

if (!parsed.spec_file?.startsWith('OUTPUT/pending-review/')) {
  throw new Error('GATE2_PATH_VIOLATION: Agent attempted to write outside pending-review/');
}
if (!parsed.schema_version === '1.0') {
  throw new Error('GATE2_SCHEMA_MISMATCH: Wrong schema version');
}
if (!parsed.task_name || parsed.task_name.length < 1) {
  throw new Error('GATE2_MISSING_TASK_NAME: task_name required');
}
if (!Array.isArray(parsed.steps) || parsed.steps.length < 1) {
  throw new Error('GATE2_MISSING_STEPS: steps array required with at least 1 step');
}
if (!Array.isArray(parsed.acceptance_criteria) || parsed.acceptance_criteria.length < 1) {
  throw new Error('GATE2_MISSING_CRITERIA: acceptance_criteria required');
}
if (!validComplexity.includes(parsed.estimated_complexity)) {
  throw new Error(`GATE2_INVALID_COMPLEXITY: must be one of ${validComplexity.join('|')}`);
}

return [{ json: { ...parsed, gate2_passed: true, gate2_timestamp: new Date().toISOString() } }];

