// Format SPEC markdown file content from validated agent output
const spec = $input.first().json;

const content = `---
title: ${spec.task_name}
type: spec
status: pending-review
agent: task-analyzer
created: ${spec.timestamp}
complexity: ${spec.estimated_complexity}
schema_version: ${spec.schema_version}
---

# SPEC: ${spec.task_name}

## Steps
${spec.steps.map((s, i) => `${i + 1}. ${s}`).join('\n')}

## Risks
${spec.risks.map(r => `- ${r}`).join('\n') || '- None identified'}

## Acceptance Criteria
${spec.acceptance_criteria.map(c => `- [ ] ${c}`).join('\n')}

---
*Generated by Task Analyzer agent · Move to \/OUTPUT\/approved\/ to proceed*
`;

return [{
  json: {
    ...spec,
    markdown_content: content,
    write_path: spec.spec_file
  }
}];

// Error handler — runs if any upstream node throws
const error = $input.first().json;
const errorMsg = error.message || error.error?.message || 'Unknown error';
const failedNode = error.node || 'unknown';

console.error(`[AI Brain Error] Node: ${failedNode} | Error: ${errorMsg}`);

// Log to audit trail (error status)
return [{
  json: {
    agent_name: 'task-analyzer',
    status: 'error',
    error_msg: errorMsg,
    failed_node: failedNode,
    timestamp: new Date().toISOString()
  }
}];
